(185, 6, 379, 566, NULL, NULL, 1, 2, 'MADURARE', 83, NULL, NULL, 'CERCASSIN', 86, 'AL·LE', 22),
(185, 6, 384, 48, NULL, NULL, 1, 4, 'DESPERTA', 73, NULL, NULL, 'SALIVANT', 95, NULL, NULL),
(185, 6, 386, 383, NULL, NULL, 2, 3, 'MOCARIES', 68, NULL, NULL, 'CALAVES', 79, 'PAL·LI', 28),
